script:
frappe.ui.form.on('Quotation', {
    quotation_to: function(frm) {
        if (frm.doc.quotation_to === 'Lead') {
            frm.set_value('naming_series', 'SAL-QTN-.YYYY.-');
        }
    },
    before_save: function(frm) {
        if (frm.doc.quotation_to === 'Lead') {
            frm.doc.naming_series = 'SAL-QTN-.YYYY.-';
        }
    }
});

frappe.ui.form.on('Lead', {
    refresh: function(frm) {
            if (frm.doc.customer) {
                        setTimeout(function() {
                                        frm.add_custom_button('View Customer', function() {
                                                            frappe.set_route('Form', 'Customer', frm.doc.customer);
                                                                            });
                                                                                        }, 500);
                                                                                                }
                                                                                                    }
                                                                                                    });

frappe.ui.form.on('Quotation', {
    quotation_to: function(frm) {
        toggle_lead_field(frm);
    },
    party_name: function(frm) {
        if (frm.doc.quotation_to == 'Lead' && frm.doc.party_name) {
            frappe.db.get_value('Lead', frm.doc.party_name, 'customer', function(r) {
                if (r && r.customer) {
                    frm.set_value('custom_customer', r.customer);
                }
            });
        } else if (frm.doc.quotation_to == 'Customer' && frm.doc.party_name) {
            frappe.db.get_value('Lead', {'customer': frm.doc.party_name}, 'name', function(r) {
                if (r && r.name) {
                    frm.set_value('custom_lead', r.name);
                }
            });
        } else if (frm.doc.quotation_to == 'Prospect' && frm.doc.party_name) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Prospect',
                    name: frm.doc.party_name
                },
                callback: function(r) {
                    if (r.message && r.message.leads && r.message.leads.length) {
                        let lead = r.message.leads[0].lead;
                        if (lead) frm.set_value('custom_lead', lead);
                    }
                }
            });
        }
    },
    refresh: function(frm) {
        toggle_lead_field(frm);

        if (frm.doc.quotation_to == 'Lead' && frm.doc.party_name && !frm.doc.custom_customer) {
            frappe.db.get_value('Lead', frm.doc.party_name, 'customer', function(r) {
                if (r && r.customer) {
                    frm.set_value('custom_customer', r.customer);
                }
            });
        } else if (frm.doc.quotation_to == 'Customer' && frm.doc.party_name && !frm.doc.custom_lead) {
            frappe.db.get_value('Lead', {'customer': frm.doc.party_name}, 'name', function(r) {
                if (r && r.name) {
                    frm.set_value('custom_lead', r.name);
                }
            });
        } else if (frm.doc.quotation_to == 'Prospect' && frm.doc.party_name && !frm.doc.custom_lead) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Prospect',
                    name: frm.doc.party_name
                },
                callback: function(r) {
                    if (r.message && r.message.leads && r.message.leads.length) {
                        let lead = r.message.leads[0].lead;
                        if (lead) frm.set_value('custom_lead', lead);
                    }
                }
            });
        }

        frm.add_custom_button(__('Create Customer'), function() {
            frappe.new_doc('Customer');
        }, __('Create'));
    }
});

function toggle_lead_field(frm) {
    let show = ['Prospect', 'Customer'].includes(frm.doc.quotation_to);
    frm.toggle_display('custom_lead', show);
}

frappe.ui.form.on('Lead', {
    refresh: function(frm) {
        if (frm.doc.__islocal) return;

        frm.add_custom_button(__('Create Prospect'), function() {
            let d = new frappe.ui.Dialog({
                title: __('Create Prospect'),
                fields: [{
                    fieldtype: 'Data',
                    fieldname: 'prospect_name',
                    label: __('Prospect Name'),
                    reqd: 1,
                    default: frm.doc.company_name || frm.doc.lead_name
                }],
                primary_action_label: __('Create'),
                primary_action: function(values) {
                    frappe.call({
                        method: 'kreatao_erpplus.overrides.quotation_patch.create_prospect_from_lead',
                        args: {
                            lead_name: frm.doc.name,
                            prospect_name: values.prospect_name
                        },
                        callback: function(r) {
                            d.hide();
                            frm.reload_doc();
                            if (r.message) {
                                frappe.set_route('Form', 'Prospect', r.message);
                            } else {
                                frappe.msgprint(__('Prospect created successfully.'));
                            }
                        }
                    });
                }
            });
            d.show();
        });

        frm.add_custom_button(__('Add to Prospect'), function() {
            let d = new frappe.ui.Dialog({
                title: __('Add to Prospect'),
                fields: [{
                    fieldtype: 'Link',
                    fieldname: 'prospect',
                    label: __('Prospect'),
                    options: 'Prospect',
                    reqd: 1
                }],
                primary_action_label: __('Add'),
                primary_action: function(data) {
                    frappe.call({
                        method: 'erpnext.crm.doctype.lead.lead.add_lead_to_prospect',
                        args: {
                            lead: frm.doc.name,
                            prospect: data.prospect
                        },
                        freeze: true,
                        freeze_message: __('Adding Lead to Prospect...'),
                        callback: function(r) {
                            d.hide();
                            frm.reload_doc();
                            frappe.msgprint(__('Lead added to Prospect successfully.'));
                        }
                    });
                }
            });
            d.show();
        });

        frm.add_custom_button(__('Create Customer'), function() {
            frappe.model.open_mapped_doc({
                method: 'kreatao_erpplus.overrides.quotation_patch.make_customer_from_lead',
                frm: frm
            });
        });

        frm.add_custom_button(__('Create Opportunity'), function() {
            frappe.db.get_value('Prospect Lead', {lead: frm.doc.name}, 'name', null, 'Prospect')
            .then(r => {
                let existing_prospect = r.message && r.message.name;
                let fields = [];

                if (existing_prospect == null) {
                    fields.push(
                        {
                            label: 'Create Prospect',
                            fieldname: 'create_prospect',
                            fieldtype: 'Check',
                            default: 1
                        },
                        {
                            label: 'Prospect Name',
                            fieldname: 'prospect_name',
                            fieldtype: 'Data',
                            default: frm.doc.company_name,
                            depends_on: 'create_prospect',
                            mandatory_depends_on: 'create_prospect'
                        }
                    );
                }

                frappe.db.get_value('Contact', {
                    first_name: frm.doc.first_name || frm.doc.lead_name,
                    last_name: frm.doc.last_name
                }, 'name').then(cr => {
                    if (cr.message == null || cr.message.name == null) {
                        fields.push({
                            label: 'Create Contact',
                            fieldname: 'create_contact',
                            fieldtype: 'Check',
                            default: '1'
                        });
                    }

                    if (fields.length) {
                        let d = new frappe.ui.Dialog({
                            title: __('Create Opportunity'),
                            fields: fields,
                            primary_action_label: __('Create'),
                            primary_action: function(data) {
                                frappe.call({
                                    method: 'create_prospect_and_contact',
                                    doc: frm.doc,
                                    args: { data: data },
                                    freeze: true,
                                    callback: function(r) {
                                        if (r.exc == null) {
                                            frappe.model.open_mapped_doc({
                                                method: 'kreatao_erpplus.overrides.quotation_patch.make_opportunity_from_lead',
                                                frm: frm
                                            });
                                        }
                                        d.hide();
                                    }
                                });
                            }
                        });
                        d.show();
                    } else {
                        frappe.model.open_mapped_doc({
                            method: 'kreatao_erpplus.overrides.quotation_patch.make_opportunity_from_lead',
                            frm: frm
                        });
                    }
                });
            });
        });

        frm.add_custom_button(__('Create Project'), function() {
            let d = new frappe.ui.Dialog({
                title: __('Create Project'),
                fields: [
                    {
                        fieldtype: 'Data',
                        fieldname: 'project_name',
                        label: __('Project Name'),
                        reqd: 1,
                        default: frm.doc.custom_project_title || frm.doc.company_name || frm.doc.lead_name
                    },
                    {
                        fieldtype: 'Data',
                        fieldname: 'custom_project_title',
                        label: __('Project Title'),
                        default: frm.doc.custom_project_title
                    },
                    {
                        fieldtype: 'Long Text',
                        fieldname: 'custom_project_detail',
                        label: __('Project Description'),
                        default: frm.doc.custom_project_description
                    }
                ],
                primary_action_label: __('Create'),
                primary_action: function(values) {
                    frappe.new_doc('Project', {
                        project_name: values.project_name,
                        custom_project_title: values.custom_project_title,
                        custom_project_detail: values.custom_project_detail,
                        custom_lead: frm.doc.name
                    });
                    d.hide();
                }
            });
            d.show();
        });

        frm.add_custom_button(__('Create Quotation'), function() {
            frappe.model.open_mapped_doc({
                method: 'kreatao_erpplus.overrides.quotation_patch.make_quotation_from_lead',
                frm: frm
            });
        });
    }
});
